using System.Collections.Generic;
namespace Grechka.Quests
{
    // Exact source matching preserves custom edits and never changes serialized quest data.
    internal static class QuestPackText
    {
        static readonly Dictionary<string, string> Keys = new Dictionary<string, string>
        {
            { "Поставьте изготовительный станок (FabricationBench) для обычного промышленного производства; подходят и его варианты T3–T5. Роботов Misc. Robots++ изготавливайте только на сборочных верстаках Grechka: каждому нужен один корпус его тира, верстак того же или более высокого тира и указанный в рецепте металл. Доступны уборщик, переносчик, кухонный бот, ремесленник, строитель, медик и OmniBot T1–T5. Матрицы, их компоненты и отдельный верстак робототехники скрыты. Простые уборщик и переносчик требуют по 20 стали, одному корпусу T1 и ремесло 4. Это необязательное ответвление: для крафта роботов достаточно сборочного верстака.", "GrechkaQuests_Pack_ee99e8262c56" },
            { "Подготовьте 20 пластали для дальнейшего развития робототехники. Роботы I собираются из 20 стали и корпуса T1; пласталь понадобится старшим корпусам и роботам. Робот каждого уровня требует один корпус своего тира и сборочный верстак Grechka того же или более высокого тира. Матрицы и их производство отключены. Исследования и навык указаны в рецепте. Покупка готовой станции позволяет пропустить подготовку крафта.", "GrechkaQuests_Pack_b76fd3c01354" },
            { "Уборщик Misc. Robots убирает грязь, но не создаёт изделия. Купите станцию или изготовьте уборщика I на сборочном верстаке Grechka T1: нужны 20 стали, один базовый корпус T1 и ремесло 4. Матрицы не требуются. Старшие верстаки сохраняют младшие рецепты. После установки подайте 250 Вт, выпустите робота и разрешите нужные помещения. Уборщик независим от переносчика: можно начать с него. Цель проверяет только станцию.", "GrechkaQuests_Pack_6964f142cdcb" },
            { "Переносчик Misc. Robots переносит предметы, но не работает на станках. Станцию можно купить или изготовить. На сборочном верстаке Grechka T1 закажите переносчика I: нужны 20 стали, один базовый корпус T1 и ремесло 4. Матрицы не требуются. Роботы старших уровней используют корпус своего тира и изготавливаются на сборочном верстаке того же или более высокого тира. После установки подайте 250 Вт, выпустите робота и разрешите зоны складов и рабочих маршрутов. Цель проверяет только станцию.", "GrechkaQuests_Pack_3987dfd31b96" },
            { "Для постоянного снабжения выберите отдельное задание «добывать сталь», «добывать пласталь» или «добывать уран». Случайный режим «Добывать металлы» сохранён для разнообразных ресурсов и редких находок. Нужны питание и выходной Factory-хоппер с разрешённым результатом во вкладке «Склад»; пустой фильтр блокирует выгрузку на 100%. Для случайного режима обязательно разрешите сталь или просто разрешите всё. В Grechka World минимально нужен корпус T2. Строить все варианты буровой для перехода к T3 не требуется.", "GrechkaQuests_Pack_Balance_8594a4235005" },
            { "На сборочном верстаке T1 откройте «Задания» и добавьте изготовление дока «МЧСник T1». Рецепт до бонусов машины: 1 корпус T1 + 60 стали + 2 обычных компонента. Нужен мастер с ремеслом 7. Дождитесь готовой упакованной станции; сам дрон уже входит в комплект. Если рецепт скрыт, проверьте «Робототехнику T1» и выбранный тип верстака. Изготовление готового комплекта засчитывается автоматически по завершённому рецепту. Покупка и установка старой станции не считаются; следующий узел проверит установленный док.", "GrechkaQuests_Pack_Balance_aa039fa7b1c8" },
            { "На сборочном верстаке T1 откройте «Задания» и добавьте изготовление дока «воин T1». Рецепт до бонусов машины: 1 корпус T1 + 60 стали + 2 обычных компонента. Нужен мастер с ремеслом 7. Дождитесь готовой упакованной станции; сам дрон уже входит в комплект. Если рецепт скрыт, проверьте «Робототехнику T1» и выбранный тип верстака. Изготовление готового комплекта засчитывается автоматически по завершённому рецепту. Покупка и установка старой станции не считаются; следующий узел проверит установленный док.", "GrechkaQuests_Pack_Balance_c0c5f030ae61" },
            { "В заданиях сборочного верстака T2 изготовьте док «МЧСник T2»: 1 корпус T2 + 80 стали + 10 пластали + 1 продвинутый компонент до бонусов машины. Требуется ремесло 8. Установите готовую станцию, подайте 400 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_d79f56500c42" },
            { "В заданиях сборочного верстака T2 изготовьте док «воин T2»: 1 корпус T2 + 80 стали + 10 пластали + 1 продвинутый компонент до бонусов машины. Требуется ремесло 8. Установите готовую станцию, подайте 400 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_49aacd933e47" },
            { "В заданиях сборочного верстака T3 изготовьте док «МЧСник T3»: 1 корпус T3 + 100 стали + 20 пластали + 2 меха-компонента T3 до бонусов машины. Требуется ремесло 9. Установите готовую станцию, подайте 650 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_37ebce9fc27a" },
            { "В заданиях сборочного верстака T3 изготовьте док «воин T3»: 1 корпус T3 + 100 стали + 20 пластали + 2 меха-компонента T3 до бонусов машины. Требуется ремесло 9. Установите готовую станцию, подайте 650 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_0f2e9a2ab77a" },
            { "В заданиях сборочного верстака T4 изготовьте док «МЧСник T4»: 1 корпус T4 + 120 стали + 30 пластали + 2 архо-компонента T4 до бонусов машины. Требуется ремесло 10. Установите готовую станцию, подайте 1000 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_e3922947f9e2" },
            { "В заданиях сборочного верстака T4 изготовьте док «воин T4»: 1 корпус T4 + 120 стали + 30 пластали + 2 архо-компонента T4 до бонусов машины. Требуется ремесло 10. Установите готовую станцию, подайте 1000 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_966d9dca2551" },
            { "В заданиях сборочного верстака T5 изготовьте док «МЧСник T5»: 1 корпус T5 + 140 стали + 40 пластали + 2 гречневых компонента T5 до бонусов машины. Требуется ремесло 11. Установите готовую станцию, подайте 1500 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_ae4217df7cca" },
            { "В заданиях сборочного верстака T5 изготовьте док «воин T5»: 1 корпус T5 + 140 стали + 40 пластали + 2 гречневых компонента T5 до бонусов машины. Требуется ремесло 11. Установите готовую станцию, подайте 1500 Вт и выпустите дрона. Дрон входит в комплект; переносчик, уборщик и док прошлого тира в рецепт не входят. Цель проверяет установленный док своего тира; зарядку, область работы и поведение проверьте после выпуска.", "GrechkaQuests_Pack_Balance_b9d7479b0fa5" },
            { "Изготовьте 8 восстановительных растворов: учитывается выпуск, не покупка. Одна партия в нарколаборатории: 3 промышленных лекарства + 4 нейтроамина → 4 раствора; нужен интеллект 5. Раствор на сутки усиливает естественное заживление в 1,75 раза, но повышает голод на 20%. Утраченные части тела он не возвращает. Готовые препараты не забираются.", "GrechkaQuests_Pack_Balance_95e01d685db1" },
            { "Изготовьте 3 иммунных препарата: 6 нейтроамина + 3 травяных лекарства → 4 дозы; интеллект 5. На сутки они ускоряют выработку иммунитета на 50%. Это помощь организму во время болезни, а не защита от нового заражения и не мгновенное удаление инфекции. Для цели нужна одна партия, применение не проверяется.", "GrechkaQuests_Pack_Balance_625bfc781f81" },
            { "Изготовьте 1 «Чистый лист»: партия 4 промышленных лекарства + 8 нейтроамина → 3 дозы; интеллект 5. Суточный курс постепенно лечит одну обычную химическую зависимость. Он не снимает люциферий, зависимость генов или толерантность. Повторная доза во время курса не даёт мгновенного повторного лечения. Книга не требует заводить зависимость: учитывается только производство препарата.", "GrechkaQuests_Pack_Balance_6f2783449322" },
            { "Изготовьте 2 инъектора «Живая ткань» на T3 или выше. В Grechka World партия: 6 промышленных лекарств + 10 нейтроамина + 6 механитов → 3 инъектора; интеллект 8. За сутки курс выполняет до 24 шагов, каждый лечит до 2 единиц одной свежей раны. Шрамы, потерянные части и бионику он не ремонтирует. Для обучения достаточно одной партии.", "GrechkaQuests_Pack_Balance_af8199cc4276" },
            { "Изготовьте 2 боевых инъектора. В Grechka World: партия 8 нейтроамина + 2 йайо + 2 промышленных лекарства + 6 механитов → 4 инъектора; интеллект 8. Эффект на 8 часов: движение ×1,25, точность стрельбы ×1,1, боль ×0,3. Затем 6 часов усталости. Это временная подготовка к бою, а не замена броне и лечению. Вводить препарат ради квеста не требуется.", "GrechkaQuests_Pack_Balance_baf04aa9d4a9" },
            { "Изготовьте 2 рабочих концентрата. В Grechka World: партия 8 нейтроамина + 2 пробудина + 2 промышленных лекарства + 6 механитов → 4 концентрата; интеллект 8. На сутки общая работа ×1,35, расход отдыха ×0,5. Затем 6 часов усталости. Препарат полезен перед большой стройкой или восстановлением базы; одинаковые дозы не складывают скорость.", "GrechkaQuests_Pack_Balance_0a2e5e0fdd02" },
            { "Постройте фармреактор T3 или выше во вкладке «Гречка». Его размер 3×2, нужен работник и 1200 Вт; скорость работы ×5. В Grechka World нужны корпус T3, 2 меха-компонента, 80 стали и 30 пластали. Реактор выпускает препараты T1–T3, а более старшие версии — ещё и свои тиры. Это рабочее место, не автономный завод: без пешки или крафтера Storage рецепты не исполняются. Готовые T4/T5 тоже подходят для цели.", "GrechkaQuests_Pack_Balance_0416f7acc164" },
            { "Постройте фармреактор T4 или выше. В Grechka World: корпус T4, 2 архо-компонента, 100 стали и 45 пластали. Версия T4 занимает 3×2, требует 3000 Вт и даёт скорость ×12. Она сохраняет ранние рецепты, открывает синтез высокотехнологичного лекарства и сыворотки шрамов и конечностей. T5 тоже подходит.", "GrechkaQuests_Pack_Balance_e9011a76e39a" },
            { "Постройте фармреактор T5. В Grechka World: корпус T5, 2 гречневых компонента, 120 стали и 60 пластали. Здание 3×2 требует 8000 Вт, скорость ×25. Все ранние рецепты сохраняются; новые конечные продукты — гречневая регенерация и омоложение. Обеспечьте устойчивое питание и запас сырья, а работу выполнит пешка или подключённый крафтер.", "GrechkaQuests_Pack_Balance_902771c9dc7a" },
            { "Поставьте изготовительный станок (FabricationBench) для обычного промышленного производства; подходят и его варианты T3–T5. Роботов Misc. Robots++ изготавливайте на сборочных верстаках Grechka: робототехнический компонент и матрица I доступны с T1, следующие матрицы и роботы — на верстаке своего тира и выше. Доступны уборщик, переносчик, кухонный бот, ремесленник, строитель, медик и OmniBot. Отдельный верстак робототехники скрыт. Простые уборщик и переносчик требуют по 20 стали, одной матрице I и ремесло 4. Это необязательное ответвление: для крафта роботов достаточно сборочного верстака.", "GrechkaQuests_Pack_ee99e8262c56" },
            { "Подготовьте 20 пластали для дальнейшего развития робототехники. С Misc. Robots++ простые роботы I собираются из стали и матрицы I; пласталь понадобится старшим матрицам и роботам. Компоненты, матрицы и роботы доступны на сборочных верстаках Grechka соответствующего или более высокого тира. Исследования и навык указаны в рецепте. Покупка готовой станции позволяет пропустить подготовку крафта.", "GrechkaQuests_Pack_b76fd3c01354" },
            { "Уборщик Misc. Robots убирает грязь, но не создаёт изделия. Купите станцию или изготовьте её. С Misc. Robots++ на сборочном верстаке Grechka T1 закажите робототехнические компоненты, матрицу I и уборщика I: для последнего нужны 20 стали, одна матрица I и ремесло 4. После установки подайте 250 Вт, выпустите робота и разрешите нужные помещения. Уборщик независим от переносчика: можно начать с него. Цель проверяет только станцию.", "GrechkaQuests_Pack_6964f142cdcb" },
            { "Переносчик Misc. Robots переносит предметы, но не работает на станках. Станцию можно купить или изготовить. С Misc. Robots++ на сборочном верстаке Grechka T1 закажите робототехнические компоненты, матрицу I и переносчика I: для последнего нужны 20 стали, одна матрица I и ремесло 4. Старшие верстаки сохраняют младшие рецепты. После установки подайте 250 Вт, выпустите робота и разрешите зоны складов и рабочих маршрутов. Цель проверяет только станцию.", "GrechkaQuests_Pack_3987dfd31b96" },
            { "Продвинутый сборочный верстак строится из корпуса T2, 60 стали, 2 обычных и 2 продвинутых компонентов. Существующий T1 можно улучшить на месте с зачётом старого корпуса и установленного оборудования. Здесь появляются меха-компонент, меха-корпус и первые улучшенные солнечные панели.", "GrechkaQuests_Pack_Balance_5860dc5e226c" },
            { "Постройте извлекатель механитов из корпуса T2, 2 продвинутых компонентов, 20 пластали и 10 урана. Обеспечьте электричество. Установка получает механиты из параллельного измерения без газа и реагентов; для её запуска не нужны меха-компоненты.", "GrechkaQuests_Pack_Balance_b221ac9ceb09" },
            { "Соберите первые 40 стали для мастерской: добыча, покупка и стартовые запасы подходят. Книга ничего не забирает. Дальнейший маршрут: запас 80 стали → базовый корпус → сборочный T1 → компоненты. Сам корпус требует 40 стали; запас нужен и для верстака. В обычной новой Grechka World исследования завершены; при включённой прогрессии проверяйте также технологии. Закрытые цели учитываются заранее.", "GrechkaQuests_Pack_Balance_b769854704d0" },
            { "Соберите запас 80 стали для корпуса и первого верстака. Сам базовый корпус требует 40 стали и 2 обычных компонента. Награда — четыре компонента: два на корпус, ещё два на сборочный верстак. Сталь можно добыть, купить или взять из стартовых запасов.", "GrechkaQuests_Pack_Balance_ab0b34ef459a" },
            { "Для базового корпуса нужны 40 стали, 2 обычных компонента и ремесло 4. Первый корпус можно собрать на ремесленном месте, последующие — там же или на любом сборочном верстаке T1–T5. На ремесленном месте можно также изготовить один компонент из 12 стали.", "GrechkaQuests_Pack_Balance_43c7c1f06d24" },
            { "Продвинутый компонент собирается из 1 обычного компонента, 12 стали, 5 пластали и 2 золота до бонусов машины. Он доступен уже на сборочном верстаке T1. Сделайте один для учебной цели, затем подготовьте два для корпуса T2. Купленные компоненты можно использовать в последующих рецептах; эта цель отмечает именно производство.", "GrechkaQuests_Pack_Balance_640bdd91f338" },
            { "На сборочном верстаке T1 соберите продвинутый корпус: базовый корпус T1 + 20 стали + 10 пластали + 2 продвинутых компонента до бонусов машины. Нужен ремесленник уровня 6. Этот корпус открывает большой выбор техники, но книга не заставляет строить её всю.", "GrechkaQuests_Pack_Balance_74c8f4f0deb9" },
            { "Подключите экстрактор к электросети и дождитесь первых 25 механитов. Это запас для нескольких меха-компонентов: базовый рецепт одного требует 10 механитов. Газ, раствор и ручная переработка не нужны.", "GrechkaQuests_Pack_Balance_0d1477277b9d" },
            { "На сборочном верстаке T2 соедините 1 продвинутый компонент, 8 пластали, 4 урана и 10 механитов до бонусов машины. Первая штука знакомит с рецептом; дальнейший запас нужен для выбранных машин, а не ради счётчика квеста.", "GrechkaQuests_Pack_Balance_04a43bfa58e0" },
            { "Изготовьте один меха-корпус: корпус T2 + 20 пластали + 2 меха-компонента + 10 механитов до бонусов машины. Предыдущий корпус используется в реальном рецепте; книга не забирает вещи. Дальше выбирайте нужную машину T3.", "GrechkaQuests_Pack_Balance_e09f134973ad" },
            { "Соберите первый архо-компонент: 1 меха-компонент + 8 пластали + 6 архо-субстрата до бонусов машины. Он используется в корпусе T4, оборудовании и поздней энергетике. Новый тир развивает цепочку своим материалом без умножения старых компонентов.", "GrechkaQuests_Pack_Balance_f501052c9da8" },
            { "Изготовьте один архо-корпус: корпус T3 + 30 пластали + 2 архо-компонента + 10 архо-субстрата до бонусов машины. Предыдущий корпус используется в реальном рецепте; книга не забирает вещи. Дальше выбирайте нужную машину T4.", "GrechkaQuests_Pack_Balance_afbbd48178e4" },
            { "Изготовьте первый гречневый компонент: 1 архо-компонент + 12 пластали + 8 гречневого концентрата до бонусов машины. Затем выбирайте, что ускорять: производство, цифровой склад, мехапонику, облучатели или энергетическую цепь.", "GrechkaQuests_Pack_Balance_3e2e17963e9c" },
            { "Изготовьте один гречневый корпус: корпус T4 + 40 пластали + 2 гречневых компонента + 10 гречневого концентрата до бонусов машины. Предыдущий корпус используется в реальном рецепте; книга не забирает вещи. Дальше выбирайте нужную машину T5.", "GrechkaQuests_Pack_Balance_fdf9879a41bb" },
            { "Запас 80 стали для мастерской", "GrechkaQuests_Pack_Balance_e6872eb6e1f6" },
            { "Приёмный бункер Factory не имеет тиров и не требует корпуса. У нового хоппера пустой фильтр: откройте вкладку «Склад» и разрешите нужные ресурсы. Для выхода дрели «Добывать металлы» проще разрешить всё; как минимум должна быть разрешена сталь. Пустой или запрещающий результат фильтр блокирует выгрузку, даже когда процесс достиг 100%.", "GrechkaQuests_Pack_HopperFactoryUntiered" },
            { "Загрузочная воронка не имеет тиров и не требует корпуса. Она хранит сырьё для соседнего раздатчика питательной пасты. Настройте фильтр подходящей еды; старые тирные воронки продолжают работать. Это необязательная ветка.", "GrechkaQuests_Pack_HopperVanillaUntiered" },
            { "Grechka World — большая книга колонии", "GrechkaQuests_Pack_30be6b849d7a" },
            { "Старт: от стали к T1", "GrechkaQuests_Pack_ac1a20ca7905" },
            { "Короткий маршрут: прочитать правила → 80 стали → базовый корпус → сборочный верстак T1 → первая серия компонентов. Урожай, кухня и украшение базы не задерживают переход к T2. Боковые ветви — выбор под свою колонию.", "GrechkaQuests_Pack_aa666e3d2ca7" },
            { "T1: мастерские и автономный быт", "GrechkaQuests_Pack_2d62b3eb9c84" },
            { "Ручные и топливные мастерские, простая защита и климат. Выбирайте нужные здания; строить весь каталог не требуется. Основной маршрут T1 находится в главе «Старт».", "GrechkaQuests_Pack_a4b5a60f3a6a" },
            { "T2: продвинутые компоненты", "GrechkaQuests_Pack_d43c67bda5ad" },
            { "Основная дорожка короткая: продвинутый компонент → продвинутый корпус → сборочный верстак T2. Каталоги цехов, энергии, обслуживания и защиты — необязательные ветви. Для T3 не нужно строить весь завод.", "GrechkaQuests_Pack_712aaaaae7c5" },
            { "T2: механика и химия", "GrechkaQuests_Pack_76cceb9bc51c" },
            { "Цех превращает доступные ресурсы в детали, материалы и лекарства. Выбирайте нужный участок: химия, механика или утилизация. Каждый станок — самостоятельная необязательная цель.", "GrechkaQuests_Pack_c8d5711051eb" },
            { "T1–T2: кухня и переработка", "GrechkaQuests_Pack_3b31ee6f2022" },
            { "Кухня, гриль, выпечка, приправы и консервы — независимые способы кормить колонию. Выберите один маршрут, остальные оставьте на потом. Урожай риса не открывает эту главу и не задерживает промышленность.", "GrechkaQuests_Pack_4f9a504ca722" },
            { "T2: электросеть и генераторы", "GrechkaQuests_Pack_8ea8f0addf9b" },
            { "Сначала источник энергии и запас, затем варианты под карту и доступное топливо. Не нужно строить все генераторы: это каталог альтернатив. Солнечная ветка вынесена в «Энергетику».", "GrechkaQuests_Pack_df9aca91623c" },
            { "T2: генераторы ARC", "GrechkaQuests_Pack_6c8c5391e8d7" },
            { "Особая боковая ветка Generator. Найденные детали и доступные в вашем сценарии варианты ARC определяют реальный маршрут. Все формы здесь альтернативны: цепочка наград не требует последовательно строить каждый ARC.", "GrechkaQuests_Pack_c5f700dbdafe" },
            { "T2: холод и выращивание", "GrechkaQuests_Pack_c9af01a15b46" },
            { "Холодильники, отопление и контролируемое выращивание решают разные задачи. Выберите подходящий размер хранилища и способ поддерживать климат, не стройте каждую модель ради продолжения книги.", "GrechkaQuests_Pack_f35d4ba544a0" },
            { "T2: связь и обслуживание", "GrechkaQuests_Pack_c5331e6a85b4" },
            { "Торговля, сканирование, доставка, двери и противопожарная инфраструктура. Эти устройства помогают основной промышленности, но не являются обязательным экзаменом перед T3.", "GrechkaQuests_Pack_13d20ccb71e9" },
            { "T2: свет и отдых", "GrechkaQuests_Pack_a5ad9cacc988" },
            { "Рабочее освещение и отдых после смены. Декоративные варианты ламп и развлечений независимы; выбирайте их по планировке базы.", "GrechkaQuests_Pack_4f71c254ca28" },
            { "T2: мехи, гены и восстановление", "GrechkaQuests_Pack_dedba86f1cb3" },
            { "Две разные ветви: механитор и генная лаборатория. Доступность специфичных операций зависит от вашей колонии и DLC; ради перехода к T3 они не требуются.", "GrechkaQuests_Pack_cea46f01bbcb" },
            { "T2: турели и огневые позиции", "GrechkaQuests_Pack_3f8bb9055fa9" },
            { "Самостоятельные варианты обороны. Дальнобойное оружие, ближние средства и специальные установки выбираются под угрозы и планировку, а не строятся обязательной цепочкой.", "GrechkaQuests_Pack_79ceef810066" },
            { "T2: бетон и фортификации", "GrechkaQuests_Pack_4cf3cb3ba376" },
            { "Бетонный цех и несколько семейств укреплений. Можно выбрать мобильное орудие, бункер или тяжёлую позицию; вся глава необязательна для промышленных тиров.", "GrechkaQuests_Pack_9a34c5149895" },
            { "T2–T3: завод Factory", "GrechkaQuests_Pack_1a3e051a1491" },
            { "Необязательный завод с настоящими машинными процессами: приём сырья → выбранный производственный участок → его продукт. Бурение, текстиль, химия, питание и медицина — параллельные направления, не одна обязательная очередь.", "GrechkaQuests_Pack_7a4e4a15dfec" },
            { "Поля, сады и рыбалка", "GrechkaQuests_Pack_2da53696fe24" },
            { "Vanilla Plants Expanded, VGP More Veggies, Farming и Fishing. Урожай учитывается отдельно от покупок; для рыбы здесь проверяется запас, а не неподтверждённое событие улова.", "GrechkaQuests_Pack_3b310035b0d8" },
            { "Паста по трубам", "GrechkaQuests_Pack_575c91a9abd8" },
            { "Vanilla Nutrient Paste Expanded. Измельчитель, бак и потребители образуют самостоятельную пищевую сеть. Кварцевый кабель Storage не заменяет трубы пасты.", "GrechkaQuests_Pack_55a8b6937b84" },
            { "Роботы и рабочие места", "GrechkaQuests_Pack_c9e808b2018d" },
            { "Misc. Robots, More Linkables и VFE Production. Освободите пешек от переноски и подготовьте удобные мастерские.", "GrechkaQuests_Pack_422f1f7f4a3c" },
            { "Цифровой склад", "GrechkaQuests_Pack_4fcc9019ddf7" },
            { "Кварц → кремний → процессоры → сеть и диски. Сначала сделайте рабочий склад, затем наращивайте объём.", "GrechkaQuests_Pack_9a6a8e49597c" },
            { "Автокрафт", "GrechkaQuests_Pack_517fb4d89f2c" },
            { "Контроллер показывает рецепты подключённых станков. Крафтер обслуживает соседей по очереди; шаблоны не требуются.", "GrechkaQuests_Pack_5856c9eb5a6e" },
            { "T3: механиты", "GrechkaQuests_Pack_9521be6801d5" },
            { "Механиты, самостоятельная ферма кристаллов и инфраструктура колонии. Мехапонику по-прежнему обслуживают пешки.", "GrechkaQuests_Pack_4a614d9822d7" },
            { "T4: архотехнологии", "GrechkaQuests_Pack_35a9968d0c32" },
            { "Архотехнологии открывают материю и облучатели. Высокая скорость требует соответствующей энергосистемы.", "GrechkaQuests_Pack_f98d0ce34137" },
            { "T5: гречневый финал", "GrechkaQuests_Pack_8be3e78c95ed" },
            { "Гречневая руда завершает основную производственную лестницу. Здесь начинается дорогая автоматизация, а не конец колонии.", "GrechkaQuests_Pack_6a3a42dd6979" },
            { "Оснащение", "GrechkaQuests_Pack_7383af1074c3" },
            { "Броня, оружие, дроны и бионика Grechka. Получить предмет — не значит установить имплант или экипировать пешку.", "GrechkaQuests_Pack_7ee31d0a5944" },
            { "Энергетика без потолка", "GrechkaQuests_Pack_12ddeaed8f90" },
            { "VFE Power и собственная солнечная лестница Grechka. Несколько независимых путей питания; поздние панели требуют предыдущие ступени.", "GrechkaQuests_Pack_0d60b3fe4a0a" },
            { "Госпиталь и запасные части", "GrechkaQuests_Pack_538457d5285b" },
            { "VFE Medical и бионика Grechka. Построить оборудование, запасти лекарства и подготовить протезы — разные задачи. Книга не проводит операции за вас.", "GrechkaQuests_Pack_eba37eb2d6ac" },
            { "Элтекс и псионика", "GrechkaQuests_Pack_ccd726d00101" },
            { "Vanilla Psycasts Expanded. Соберите элтекс и снаряжение; развитие псионика происходит по правилам самого мода. Книга не начисляет уровни или способности.", "GrechkaQuests_Pack_2e083ff60ecf" },
            { "За пределами базы", "GrechkaQuests_Pack_86e39d1087c0" },
            { "Pirates, The Generator, Cryptoforge и другие приключения. События назначает рассказчик. Книга отмечает ваши материальные трофеи, а не подменяет завершение чужих сюжетов.", "GrechkaQuests_Pack_687404d10e5f" },
            { "Библиотека и полигон", "GrechkaQuests_Pack_81634b77b481" },
            { "Vanilla Books Expanded и Misc. Training. Развитие колонии — не только корпуса. Подготовьте место для книг и тренировок.", "GrechkaQuests_Pack_848850e4baa0" },
            { "Жить красиво", "GrechkaQuests_Pack_533382e123c1" },
            { "Spacer, Neat Storage и Fridge. Побочные цели на устройство жилой базы, мастерской и склада. Каждый предмет остаётся в вашей колонии.", "GrechkaQuests_Pack_8ee4abef72c0" },
            { "Производственные вехи", "GrechkaQuests_Pack_b4e587360acd" },
            { "Необязательные рекорды производства. Эти ветки не блокируют основную игру; закрытые цели тоже накапливаются.", "GrechkaQuests_Pack_a2ac12ddc312" },
            { "Ачивки: зачем? Потому что могу", "GrechkaQuests_Pack_c6abf4b13e1b" },
            { "Необязательные рекорды с лаки-блоками. Убийства и забой считаются только с установленной версией счётчика, от действий колонии; найденные трупы не подходят. Прошлое старого сейва восстановить нельзя.", "GrechkaQuests_Pack_3341daaebeaf" },
            { "Здесь решает производство", "GrechkaQuests_Pack_37141e4a6897" },
            { "Все исследования в новой Grechka World уже завершены. Доступность машины определяют её материалы, компоненты и корпус. Книга ничего не забирает и не открывает рецепты. Даже закрытые задания учитывают цели заранее; награда доступна после предыдущих заданий. Клавиша книги по умолчанию — 5, её можно изменить в настройках. Прочитайте и отметьте цель вручную.", "GrechkaQuests_Pack_9ad5fc8b900c" },
            { "80 стали для базового корпуса", "GrechkaQuests_Pack_bd721caa6e93" },
            { "Для базового корпуса нужны 80 стали и 4 обычных компонента. Сталь можно добыть, купить или взять из стартовых запасов. Получите награду — четыре компонента — и сразу переходите к корпусу.", "GrechkaQuests_Pack_eb344f363f63" },
            { "Рис: первый урожай", "GrechkaQuests_Pack_6edb9124559c" },
            { "Необязательное ответвление. Соберите 30 риса, когда колония сама дойдёт до урожая. Промышленный маршрут не зависит от этой цели: ждать роста растений ради T1 или T2 не нужно.", "GrechkaQuests_Pack_3f363c08711b" },
            { "Сборочный верстак T1", "GrechkaQuests_Pack_59ca140583e0" },
            { "Постройте базовый сборочный верстак: базовый корпус T1 + 60 стали + 2 обычных компонента. На нём доступны серии обычных компонентов, продвинутые компоненты и продвинутый корпус T2.", "GrechkaQuests_Pack_d7f4eae6e63f" },
            { "Базовый корпус T1", "GrechkaQuests_Pack_f06e9abebcea" },
            { "На ремесленном месте изготовьте базовый корпус: 80 стали + 4 обычных компонента. Работа требует ремесла 4. Сборочный верстак для этого рецепта ещё не нужен. Если компонентов нет, на том же месте есть ручной рецепт: 12 стали → 1 компонент.", "GrechkaQuests_Pack_44a3ab932a78" },
            { "Для базового корпуса нужны 80 стали, 4 обычных компонента и ремесло 4. Первый корпус можно собрать на ремесленном месте, последующие — там же или на любом сборочном верстаке T1–T5. На ремесленном месте можно также изготовить один компонент из 12 стали.", "GrechkaQuests_Pack_44a3ab932a78" },
            { "Одна серия: 5 компонентов", "GrechkaQuests_Pack_210663951c87" },
            { "Сделайте одну серию обычных компонентов на сборочном верстаке: 60 стали → 5 компонентов до бонусов машины. Этого достаточно для учебной цели. Большие серии вынесены в необязательные вехи и ачивки.", "GrechkaQuests_Pack_5061f7f336db" },
            { "Продвинутый корпус T2", "GrechkaQuests_Pack_6872881ffaf8" },
            { "На сборочном верстаке T1 соберите продвинутый корпус: базовый корпус T1 + 40 стали + 20 пластали + 4 продвинутых компонента. Нужен ремесленник уровня 6. Этот корпус открывает большой выбор техники, но книга не заставляет строить её всю.", "GrechkaQuests_Pack_a729471b0730" },
            { "Сборочный верстак T2", "GrechkaQuests_Pack_0447cbc9b9df" },
            { "Продвинутый сборочный верстак строится из корпуса T2, 80 стали, 4 обычных и 2 продвинутых компонентов. Существующий T1 можно улучшить на месте. Здесь появляются меха-компонент, меха-корпус и первые улучшенные солнечные панели.", "GrechkaQuests_Pack_af5c9035f464" },
            { "Продвинутый компонент", "GrechkaQuests_Pack_4a546dc65da4" },
            { "Продвинутые компоненты уже можно делать на сборочном верстаке T1: отдельный верстак T2 для первого компонента не нужен. Сделайте один, затем подготовьте четыре для продвинутого корпуса. Компоненты также разрешено покупать. Покупка помогает с материалами последующих рецептов, но эта учебная цель отмечает именно производство одного компонента.", "GrechkaQuests_Pack_c229ab85be5d" },
            { "Белые жилы", "GrechkaQuests_Pack_bada6199d355" },
            { "Добудьте 30 кварца из жил. Кварц также продаётся и встречается в минеральных метеоритах; для этой цели нужна именно добыча.", "GrechkaQuests_Pack_66abca4038ae" },
            { "Электрический высекатель", "GrechkaQuests_Pack_93dba8116271" },
            { "Высекатель выпускает кварцевые, серебряные и золотые процессоры. Прессы и шаблоны не нужны: выберите рецепт, подготовьте кремниевую подложку и нужный материал. Это рабочее начало электронной цепочки Storage. В Grechka World минимально нужен корпус T1. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_3dd79a227ce4" },
            { "Кварцевая логика", "GrechkaQuests_Pack_80ed4841327e" },
            { "Изготовьте 8 кварцевых процессоров. Внимательно смотрите промежуточные рецепты: кварцевая пыль и кремний нужны для подложек.", "GrechkaQuests_Pack_0c0f2a788a48" },
            { "Один контроллер, вся сеть", "GrechkaQuests_Pack_d60d2276c21a" },
            { "Постройте контроллер 1×1. Он открывает склад, диски, устройства и автокрафт. Подземный кварцевый кабель передаёт сигнал; электричество требует отдельного питания. Дополнительный контроллер не добавляет каналов: каналов здесь нет.", "GrechkaQuests_Pack_4640b89252ac" },
            { "Диски хранят настоящие вещи", "GrechkaQuests_Pack_3e5718c015bb" },
            { "Постройте дисковый блок 1×1, соедините сигнальным кабелем и установите диск через контроллер. На каждом диске 63 типа, объём зависит от размера; свойства предметов сохраняются. Цель проверяет здание, а не исправность сети.", "GrechkaQuests_Pack_8cb098e1c8ff" },
            { "Первый килобайт", "GrechkaQuests_Pack_9b1cda709352" },
            { "Иметь диск 1K. Закажите приём вещей через контроллер: пешка перенесёт их физически. Выдача также идёт переноской. Обычные диски сохраняют порчу пищи; морозильные замораживают её даже в караване. Кнопка оптимизации перераспределяет предметы по размерам дисков.", "GrechkaQuests_Pack_586f4aae5219" },
            { "Кристаллическая ферма", "GrechkaQuests_Pack_97df51be10f5" },
            { "Найдите событие метеорита на мировой карте и отправьте караван. Привезите сертус-кварц и переносимый источник кристаллов. Источник можно установить на базе и окружить ускорителями. Это цель наличия кварца, не проверка посещения события.", "GrechkaQuests_Pack_289c85a86bdb" },
            { "Экстрактор механитов T3", "GrechkaQuests_Pack_cef5d3667f13" },
            { "Постройте извлекатель механитов и обеспечьте электричество. Он получает материал из параллельного измерения. Газовая цепочка не нужна.", "GrechkaQuests_Pack_90114ed7122a" },
            { "Первый поток механитов", "GrechkaQuests_Pack_fb1a0f3646da" },
            { "Подключите экстрактор к электросети и дождитесь первых 25 механитов — это материал для одного меха-компонента. Газ, раствор и ручная переработка не нужны.", "GrechkaQuests_Pack_b26e5a443a4b" },
            { "Меха-компонент T3", "GrechkaQuests_Pack_c1de9affa449" },
            { "На сборочном верстаке T2 соедините 4 продвинутых компонента, 20 пластали, 10 урана и 25 механитов. Первая штука знакомит с рецептом; дальнейший запас нужен уже для ваших машин, а не ради счётчика квеста.", "GrechkaQuests_Pack_b7ac216867c9" },
            { "Мехапоника T3: одна клетка", "GrechkaQuests_Pack_22f6a40861ca" },
            { "Постройте мехапонику T3: рост ×5, питание 500 Вт, без света и питательного раствора. Сеют и собирают пешки. Поздние T4/T5 растят ещё быстрее и потребляют больше энергии.", "GrechkaQuests_Pack_d95b0473d3e0" },
            { "Ионизатор T3: чистая комната", "GrechkaQuests_Pack_f62b198e52b6" },
            { "Ионизатор освещает и очищает всю комнату от грязи, крови и следов. Постройте один, подключите питание и оцените его в рабочем помещении.", "GrechkaQuests_Pack_7eac2a0ad190" },
            { "Стационарный работник", "GrechkaQuests_Pack_4408657611b0" },
            { "Поставьте крафтер 1×1 рядом со станками и соедините с кварцевой сетью. Он обслуживает до четырёх соседей и выполняет по одному циклу по кругу. Тир крафтера отвечает за скорость работника, тир станка — за его собственные бонусы.", "GrechkaQuests_Pack_e9d7da9eaa6b" },
            { "Без шаблонов", "GrechkaQuests_Pack_25dcebb66023" },
            { "Откройте автокрафт контроллера. Он показывает реальные рецепты подключённых станков: шаблоны создавать не надо. Закажите изделие, проверьте недостающие материалы и настройте минимальный остаток. Отметка ручная: книга не выдаёт заказ за выполненный автоматически.", "GrechkaQuests_Pack_9b6e62f8a9bb" },
            { "Архо-субстрат", "GrechkaQuests_Pack_2aa334babfdf" },
            { "Синтезируйте первую единицу архо-субстрата. Для этой ветки важен запуск процесса, а не дополнительная партия ради книги. Найденный или купленный материал также можно использовать в реальных рецептах, но цель отмечает именно синтез.", "GrechkaQuests_Pack_8c180da1517d" },
            { "Архо-компонент T4", "GrechkaQuests_Pack_4a6ab0057595" },
            { "Соберите первый архо-компонент из материалов предыдущего тира и архо-субстрата. Он используется в корпусе T4, оборудовании и поздней энергетике. Крупные объёмы не нужны для завершения этого учебного шага.", "GrechkaQuests_Pack_ec816e524cca" },
            { "Архо-генератор T4", "GrechkaQuests_Pack_a5e7d49deab9" },
            { "Постройте архо-генератор T4. Он обеспечивает постоянную мощность без топлива, аварий и охлаждения. Для длинных цепочек материи понадобится ещё больше энергии.", "GrechkaQuests_Pack_2bf9b9e1f785" },
            { "Первая материя", "GrechkaQuests_Pack_49c8abacd0b8" },
            { "Получите первые 10 единиц материи из генератора. Теперь сырьё можно направить в синтезатор. Эта ветка необязательна для самого гречневого компонента.", "GrechkaQuests_Pack_184f9879a4df" },
            { "Гречка из недр", "GrechkaQuests_Pack_b8dc16b1d0db" },
            { "Добыть первые 10 единиц гречневой руды — необязательно разрабатывать всю жилу ради знакомства. Руда ведёт к концентрату и финальному гречневому компоненту.", "GrechkaQuests_Pack_2a74e66a9ad1" },
            { "Гречневый концентрат", "GrechkaQuests_Pack_1f16803792d6" },
            { "Переработайте гречневую руду в первый гречневый концентрат. Это общий подготовленный ресурс T5: его используют компоненты и поздние машины.", "GrechkaQuests_Pack_65fcf125079e" },
            { "Гречневый компонент T5", "GrechkaQuests_Pack_9d3e8c55e191" },
            { "Изготовьте первый гречневый компонент. Дальше выбирайте, что ускорять: производство, цифровой склад, мехапонику, облучатели или энергетическую цепь.", "GrechkaQuests_Pack_ce0953869b81" },
            { "Гречневая солнечная панель S6", "GrechkaQuests_Pack_86b0fe383acb" },
            { "Постройте финальную панель S6. Её цепочка начинается с обычной ванильной солнечной панели и последовательно использует предыдущие ступени. Ориентир — одна на позднюю базу, три на базу с материей; реальные нагрузки зависят от числа машин.", "GrechkaQuests_Pack_72e0a9a12833" },
            { "Меха-защита", "GrechkaQuests_Pack_cde34a3c24b0" },
            { "Получите броню T3. Оснащение имеет три ступени T3–T5; золотые крылья высшей ступени — отдельный совместимый элемент внешнего вида.", "GrechkaQuests_Pack_cb5a177274d9" },
            { "Холодная очередь", "GrechkaQuests_Pack_5c744cfc5c69" },
            { "Получите криовинтовку. Базовый урон одной пули — 100, очередь — 10, дальность фиксирована. Очередь не является отдельной системой магазинов.", "GrechkaQuests_Pack_aa56f55d4f30" },
            { "Дрон-спутник", "GrechkaQuests_Pack_a8d101e2a5a3" },
            { "Получите боевого дрона T4 и установите в utility-слот. Он атакует рядом с владельцем; цель проверяет наличие предмета, а не боевой счёт.", "GrechkaQuests_Pack_dda61500b6c2" },
            { "Мифическая анатомия", "GrechkaQuests_Pack_5a3acca56936" },
            { "Получите мифическую руку T4: эффективность 300%. Гречневые аналоги T5 дают 600%. Операции следуют человеческой анатомии, другие тела требуют совместимых адаптеров.", "GrechkaQuests_Pack_1e23df07031c" },
            { "Совместимые семейства чипов", "GrechkaQuests_Pack_b8e2f5075376" },
            { "Разные семьи чипов совместимы. Новый тир одной семьи заменяет предыдущий, а снятый аналог возвращается предметом. Боевые чипы могут встречаться у быстрых рейдеров: событие выбирает рассказчик. Книга не проверяет автоматически операцию или победу.", "GrechkaQuests_Pack_7ff99eeeeaaf" },
            { "Серийная промышленность", "GrechkaQuests_Pack_8d40a3577318" },
            { "Необязательная производственная веха: выпустите 100 продвинутых компонентов за время активной книги. Старый склад не превращается задним числом в производство.", "GrechkaQuests_Pack_ee7334ec6193" },
            { "Запас цифровой логики", "GrechkaQuests_Pack_b0f982619e9f" },
            { "Необязательная цель наличия: 100 кварцевых процессоров. Покупка и изготовление подходят одинаково. Диски сети тоже входят в поддерживаемый учёт имущества.", "GrechkaQuests_Pack_3ab0bc5e4b5a" },
            { "Машины работают — колония живёт", "GrechkaQuests_Pack_c4e21c28b780" },
            { "Вы прошли основную производственную цепочку. Дальше стройте собственную систему, масштабируйте материю и настраивайте остатки. Книга переносится JSON-файлом; авторский режим позволяет сделать свои главы и награды.", "GrechkaQuests_Pack_1bc10ffad4ea" },
            { "Автоматическая буровая платформа", "GrechkaQuests_Pack_52576bfe92fa" },
            { "Буровая добывает ресурсы своим штатным способом. Сначала проверьте участок добычи и питание, затем подготовьте место для выходящего сырья. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_cfd0235677b5" },
            { "Приёмный бункер Factory", "GrechkaQuests_Pack_7ddf1a08d98c" },
            { "Приёмный бункер подаёт лежащие в нём ингредиенты соседнему оборудованию. Настройте фильтр сырья и проверьте фактическое соседство. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_100bcc3f1d35" },
            { "Лента пошла", "GrechkaQuests_Pack_79cb5a0cbdee" },
            { "Постройте три сегмента конвейера и продумайте направление движения. Книга проверяет количество ваших построек.", "GrechkaQuests_Pack_bc6195043e27" },
            { "Автоматическая плавильня", "GrechkaQuests_Pack_b614b05e44d3" },
            { "Плавильня возвращает полезный металл из подходящего сырья и ненужных предметов. Выберите конкретный рецепт и проверьте выход перед переработкой ценных вещей. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_61b31913a7ce" },
            { "Серийный цех", "GrechkaQuests_Pack_83dcdd3f92e7" },
            { "Автосборщик выпускает изделия своим штатным процессом. Позже крафтер Storage сможет снабжать его из дисков.", "GrechkaQuests_Pack_ce860910aae8" },
            { "Автоматическая биотопливная установка", "GrechkaQuests_Pack_d0bbeeb38f0f" },
            { "Биотопливная установка перерабатывает подходящую органику в химтопливо. Организуйте подачу сырья и выход топлива; этим потоком можно снабжать генераторы и транспорт. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_84a3e3197c1c" },
            { "Запах индустриализации", "GrechkaQuests_Pack_a7956331e4c4" },
            { "Произведите суммарно 250 химтоплива обычными рецептами или поддержанной фабрикой. Переноска и покупка не увеличивают счётчик.", "GrechkaQuests_Pack_0b87f6e5a97d" },
            { "Сталь — только начало", "GrechkaQuests_Pack_4925581cf463" },
            { "Сплавная печь даёт следующий шаг металлургии. Откройте её процессы и организуйте подачу ингредиентов.", "GrechkaQuests_Pack_ad09ab440290" },
            { "Пласталь с конвейера", "GrechkaQuests_Pack_9b397cd76733" },
            { "Выпустите 200 пластали. Покупные запасы могут помочь стройке, но не заменяют производство этой ачивки.", "GrechkaQuests_Pack_921950669c18" },
            { "Основа аптечки", "GrechkaQuests_Pack_46d971d8e93b" },
            { "Постройте синтезатор нейтроамина. Его результат связывает химическую и медицинскую ветки.", "GrechkaQuests_Pack_a158dccf562a" },
            { "Нейтроамин больше не дефицит", "GrechkaQuests_Pack_8050627b844a" },
            { "Произведите 100 нейтроамина через поддержанный процесс Factory. Торговля остаётся доступной, но это именно производственная веха.", "GrechkaQuests_Pack_75a35c95ad82" },
            { "Аптека промышленного масштаба", "GrechkaQuests_Pack_6ade75f8c11e" },
            { "Подготовьте гранулятор лекарств и сырьё для выбранного процесса. Нейтроамин нужен не только на продажу.", "GrechkaQuests_Pack_60ce07e6331c" },
            { "Белые халаты довольны", "GrechkaQuests_Pack_4786f5fb32d5" },
            { "Произведите сто промышленных лекарств. Они остаются у колонии и пригодятся следующему рейду.", "GrechkaQuests_Pack_5f0b01dab3fc" },
            { "Автоматический ткацкий станок", "GrechkaQuests_Pack_ad9c5e54281a" },
            { "Ткацкая машина ведёт собственные производственные процессы. Выберите нужный текстиль и организуйте подачу сырья вместо ручного ожидания у каждого заказа. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_0d2f7385ad3d" },
            { "Синтетика без дефицита", "GrechkaQuests_Pack_84ad94220ba5" },
            { "Автоткацкая машина Factory выпускает синтеткань. Произведите 100 единиц для серийной одежды и экипировки.", "GrechkaQuests_Pack_fd4decde0ad8" },
            { "Автоматическая ферма", "GrechkaQuests_Pack_4dd9334c52a5" },
            { "Автоферма обслуживает свою рабочую полосу. Проверьте направление, посевную зону и выгрузку урожая; наличие машины само по себе не размечает всё поле. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_bfe94d43d939" },
            { "Рыба заводская", "GrechkaQuests_Pack_c18cbff9e86b" },
            { "Автоматическая рыбная ферма дополняет обычную рыбалку. Подготовьте собственную пищевую цепочку.", "GrechkaQuests_Pack_de51abae306b" },
            { "Электрическая суповарка", "GrechkaQuests_Pack_d7b66ccb6d7b" },
            { "Суповарка готовит супы крупной партией. Сравните размер партии с запасами и числом едоков, затем настройте постоянный запас еды. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_9522ea4f17e5" },
            { "Первый котёл готов", "GrechkaQuests_Pack_3babb3aa231a" },
            { "Соберите запас из 10 готовых простых супов. Незавершённая заготовка не подходит.", "GrechkaQuests_Pack_8f905fe954c2" },
            { "Гриль", "GrechkaQuests_Pack_8ab6cda56f1d" },
            { "Гриль добавляет отдельные рецепты жареной еды. Это альтернатива обычной плите: выберите подходящие продукты и приготовьте еду для колонии. В Grechka World минимально нужен корпус T1. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_873dc56f49a9" },
            { "Пикник на окраине", "GrechkaQuests_Pack_968f2589d093" },
            { "Приготовьте или приобретите десять порций простого гриля. Это запас готовой еды, не счётчик поедания.", "GrechkaQuests_Pack_d03b346656a3" },
            { "Электрическая пекарная печь", "GrechkaQuests_Pack_2f6437af3053" },
            { "Электрическая печь выпускает выпечку. Подготовьте ингредиенты выбранного рецепта; мука и добавки связывают её с соседним кухонным производством. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_339f04f37673" },
            { "Мука для будущего торта", "GrechkaQuests_Pack_0e4b89280a9b" },
            { "Соберите 100 муки и посмотрите рецепты Bakery. Купленная мука тоже подходит.", "GrechkaQuests_Pack_73917175096c" },
            { "Торт пережил рейд", "GrechkaQuests_Pack_4ece9057a0f7" },
            { "Двадцать простых кондитерских изделий — повод устроить маленький праздник. Квест их не съест.", "GrechkaQuests_Pack_20a86d1ed90d" },
            { "Консервный аппарат", "GrechkaQuests_Pack_9456b43fe431" },
            { "Консервный аппарат готовит консервы для запаса и перевозки. Выберите доступные продукты и рецепт, чтобы хранить часть урожая в удобном виде. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_0129a509981f" },
            { "Запас на чёрный день", "GrechkaQuests_Pack_f5e59cbbd6b3" },
            { "Соберите 30 овощных консервов. Это пищевой резерв, который можно расходовать после получения отметки.", "GrechkaQuests_Pack_d0cc3e58c8f1" },
            { "Котёл для рагу", "GrechkaQuests_Pack_dc9dfb62b32c" },
            { "Котёл готовит рагу. Это отдельный кухонный маршрут с собственными рецептами: подберите ингредиенты под доступные запасы. В Grechka World минимально нужен корпус T1. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_4d2abe37e944" },
            { "Рагу готово", "GrechkaQuests_Pack_ff67ccf6d877" },
            { "Соберите десять порций изысканного рагу. Получение еды из торговли тоже засчитывается.", "GrechkaQuests_Pack_305d276f1dbc" },
            { "Стол приправ", "GrechkaQuests_Pack_f63ae0496988" },
            { "Стол приправ выпускает пищевые добавки, включая кетчуп. Поддерживайте небольшой запас нужной приправы рядом с кухней. В Grechka World минимально нужен корпус T1. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_57f95f9cb989" },
            { "Красный стратегический резерв", "GrechkaQuests_Pack_ff5cdbe5c2c9" },
            { "Пятьдесят единиц кетчупа. Никакой практической необходимости завершать эту задачу нет; в этом её смысл.", "GrechkaQuests_Pack_aad4adc88d0a" },
            { "Спринклер", "GrechkaQuests_Pack_4f5c1ad202b7" },
            { "Спринклер обслуживает выращивание растений вокруг себя. Разместите его по реальной зоне действия и обеспечьте питание. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_fc36c45a3adb" },
            { "Кусочек другого климата", "GrechkaQuests_Pack_62e5d220ccd2" },
            { "Искусственная экосистема — ещё один вариант выращивания наряду с мехапоникой.", "GrechkaQuests_Pack_4d15373b5edb" },
            { "Свой яблоневый сад", "GrechkaQuests_Pack_70b5737dec09" },
            { "Vanilla Plants Expanded: соберите 100 яблок с растений. Покупка фруктов не считается урожаем.", "GrechkaQuests_Pack_0aaff250676e" },
            { "Томатная дипломатия", "GrechkaQuests_Pack_0e285647480d" },
            { "Соберите 250 помидоров VPE. Для помидоров VGP есть отдельная ветка: разные определения не сливаются без явного правила.", "GrechkaQuests_Pack_24a57b6e0773" },
            { "Зайцам не досталось", "GrechkaQuests_Pack_a5437f18b97c" },
            { "VGP More Veggies: соберите сотню моркови. Растительная ветка не требует проходить Factory.", "GrechkaQuests_Pack_f609b27d29d0" },
            { "База с авокадо", "GrechkaQuests_Pack_87ff4b79a636" },
            { "Вырастите и соберите 100 авокадо VGP. Найденные фрукты не увеличат этот счётчик.", "GrechkaQuests_Pack_94838d03b011" },
            { "Рыбный день", "GrechkaQuests_Pack_49701c8ec555" },
            { "Vanilla Fishing Expanded: накопите 30 лососей. Цель проверяет запас — улов и покупка подходят одинаково.", "GrechkaQuests_Pack_d2ac8a88f26f" },
            { "Рыбный прилавок", "GrechkaQuests_Pack_85fbb4b2e04a" },
            { "Соберите по 15 тунцов, трески и форели. Каждая достигнутая цель запоминается отдельно: рыбу можно пустить на кухню.", "GrechkaQuests_Pack_af0bc9f793f8" },
            { "15 трески", "GrechkaQuests_Pack_aafe7d1ce58c" },
            { "15 форели", "GrechkaQuests_Pack_d548e9341cfc" },
            { "Измельчитель питательной пасты", "GrechkaQuests_Pack_60a435fd59b8" },
            { "Часть системы питательной пасты. Измельчитель готовит пасту, бак хранит её, а конечные устройства распределяют; свяжите нужные части трубами. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_ef0ffb9673e1" },
            { "Бак питательной пасты", "GrechkaQuests_Pack_0a50f521ea00" },
            { "Обед в трубопроводе", "GrechkaQuests_Pack_ae25417dd05b" },
            { "Проложите пять сегментов скрытой трубы. Это отдельная сеть, электричество подводится обычными проводами.", "GrechkaQuests_Pack_cbee7e3a7cf6" },
            { "Кран питательной пасты", "GrechkaQuests_Pack_0ecb11d98e1b" },
            { "Кормушка питательной пасты", "GrechkaQuests_Pack_0b47b58fa0e9" },
            { "Капельница питательной пасты", "GrechkaQuests_Pack_d330d48c8c71" },
            { "Наняли грузчика", "GrechkaQuests_Pack_212aa8131756" },
            { "Misc. Robots: установите базовую станцию переносчика. Сам робот и его зарядка работают по правилам Misc. Robots.", "GrechkaQuests_Pack_f285ea94fdf0" },
            { "Швабра с характером", "GrechkaQuests_Pack_2baf96674656" },
            { "Поставьте станцию уборщика. До ионизатора Grechka эта ветка помогает с обычной грязью.", "GrechkaQuests_Pack_36182f4fe0cc" },
            { "Большой механический станок", "GrechkaQuests_Pack_092f2b48f4e3" },
            { "Большой механический станок обслуживает производство оружия и механических изделий. Выберите нужное колонии снаряжение и обеспечьте мастеру сырьё. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_7e82685c86ed" },
            { "Инструмент на расстоянии руки", "GrechkaQuests_Pack_1b5accd33077" },
            { "Шкаф механика полезен рядом с совместимым рабочим местом. Цель фиксирует постройку, а не активную связь бонуса.", "GrechkaQuests_Pack_2709ad5a4c25" },
            { "Электрический камнерезный стол", "GrechkaQuests_Pack_e38e594bece9" },
            { "Камнерезный стол перерабатывает обломки в блоки для строительства. Разместите сырьё рядом, чтобы переноска не съедала всё рабочее время. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_9ccb0b350b65" },
            { "Большой швейный стол", "GrechkaQuests_Pack_f94fb402e017" },
            { "Швейное рабочее место превращает ткань и кожу в одежду. Материал и качество выбираются в заказе, поэтому начните с реально нужного колонии комплекта. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_bcae10cb4168" },
            { "Бетономешалка", "GrechkaQuests_Pack_b1de57514c05" },
            { "Бетономешалка выпускает бетон для фортификаций. Начните с партии под конкретную стройку, затем направьте материал на выбранные укрепления. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_2244ffd4a4fd" },
            { "Не деревянная коробка", "GrechkaQuests_Pack_65c959016831" },
            { "Накопите 500 бетонных блоков. Их можно сразу потратить на периметр — после достижения цель остаётся выполненной.", "GrechkaQuests_Pack_a366a83ac2b2" },
            { "Токарный станок", "GrechkaQuests_Pack_32db76456219" },
            { "Токарный станок выпускает усиленные стволы и механические детали. Свяжите его с выбранным орудием, чтобы готовить реальные комплектующие оборонного цеха. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_19dc65cdf4a1" },
            { "Электродуговая печь", "GrechkaQuests_Pack_ee0fe3e979f7" },
            { "Электродуговая печь переплавляет металлический лом в сталь. Во время работы она выделяет много тепла: предусмотрите для неё подходящее помещение. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_82d94f79f667" },
            { "Пиролизная установка", "GrechkaQuests_Pack_90d28d48aac2" },
            { "Пиролизная установка выпускает химтопливо. Организуйте его запас для генераторов или других потребителей, а не только накопление ради квеста. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_507a32f91dd0" },
            { "Бункер с автотурелью", "GrechkaQuests_Pack_9be7da9fddef" },
            { "Укреплённая огневая позиция объединяет защиту и вооружение. Проверьте необходимость расчёта, доступ к позиции и направление стрельбы. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_9b3b2771642b" },
            { "Полевая гаубица", "GrechkaQuests_Pack_3167c5f5849c" },
            { "Дальнобойная огневая позиция поддерживает оборону на дистанции. Проверьте её боеприпасы, минимальную дистанцию и безопасную зону огня перед использованием. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_be51a5f3c451" },
            { "Радиотерминал", "GrechkaQuests_Pack_20338f9b03c5" },
            { "Радиоустройство добавляет штатные функции связи или отдыха своего мода. Разместите его там, где им смогут пользоваться колонисты. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_340055d310b4" },
            { "Антенная башня", "GrechkaQuests_Pack_84bf92844d73" },
            { "Антенная башня совмещает торговый маяк и ретранслятор управления механоидами. Внутренняя область обслуживает торговлю, внешняя — управление; башня также может привлекать орбитальных торговцев. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_e5edb8738f2c" },
            { "Энергия про запас", "GrechkaQuests_Pack_dcb2d66292c3" },
            { "VFE Power: продвинутый аккумулятор сглаживает работу переменных источников.", "GrechkaQuests_Pack_ea7adf6c41e7" },
            { "Ветер перемен", "GrechkaQuests_Pack_7f810edd0bc6" },
            { "Продвинутая турбина — альтернативный источник между солнечными ступенями. Учитывайте свободное пространство.", "GrechkaQuests_Pack_eb519c97c9f7" },
            { "Мирный атом", "GrechkaQuests_Pack_b7dae4fde225" },
            { "Реактор VFE Power — самостоятельный путь энергии. Солнечная лестница не является единственным выбором.", "GrechkaQuests_Pack_600899045f66" },
            { "Солнце: первый апгрейд", "GrechkaQuests_Pack_4a1532d5495d" },
            { "Начните с ванильной солнечной панели и соберите первую улучшенную ступень. На этой ветке старые панели становятся материалом для новых.", "GrechkaQuests_Pack_33d5a15d9c5d" },
            { "Солнце: собираем в серию", "GrechkaQuests_Pack_0fb10a1c480d" },
            { "Сборка становится серийной: для следующей панели потребуется уже несколько предыдущих. Удобный момент подготовить отдельный заказ фотоэлементов.", "GrechkaQuests_Pack_af544b9c3924" },
            { "Солнце: механическая ступень", "GrechkaQuests_Pack_6af366db182f" },
            { "Механическая ступень связывает компоненты и фотоэлементы T3. Подготовьте запас материалов до разборки действующей электростанции.", "GrechkaQuests_Pack_4ac99f96f1be" },
            { "Солнце: предел старого цеха", "GrechkaQuests_Pack_3d0e1997ad75" },
            { "Соберите следующую ступень из шести предыдущих панелей. Солнечная ветка начинает проверять пропускную способность всего производства.", "GrechkaQuests_Pack_ba14008d3612" },
            { "Солнце: архо-масштаб", "GrechkaQuests_Pack_9befea0448c4" },
            { "Архо-ступень поглощает ещё шесть предыдущих панелей. Следующая остановка — гречневый финал; запланируйте одновременно компоненты, корпуса и фотоэлементы.", "GrechkaQuests_Pack_e65ee3e183d0" },
            { "Сеть ловит свет", "GrechkaQuests_Pack_16796048e2cb" },
            { "Опциональная ветка Storage использует материалы цифровой сети. Она дополняет основную солнечную лестницу.", "GrechkaQuests_Pack_0725772c9b56" },
            { "Солнце за бетоном", "GrechkaQuests_Pack_8365edc33282" },
            { "Панель ветки Fortifications связывает солнечную энергетику с промышленностью этого мода.", "GrechkaQuests_Pack_a6e0cf2c703b" },
            { "Операционная без импровизации", "GrechkaQuests_Pack_7baaf9a2b4e8" },
            { "VFE Medical: подготовьте операционный стол. Эта цель не требует проводить операцию.", "GrechkaQuests_Pack_81e1328a01f2" },
            { "Центр жизненных показателей", "GrechkaQuests_Pack_b7bac5608ae8" },
            { "Монитор жизненных показателей обслуживает медицинские места. Проверьте его связь с койками: отдельно стоящий монитор не заменяет врача. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_512e272bf0d6" },
            { "Лекарства до рейда", "GrechkaQuests_Pack_0ce38b334641" },
            { "Держите запас из 50 промышленных лекарств. Их не нужно отдавать книге.", "GrechkaQuests_Pack_ab4579c3a6c0" },
            { "Аптека с грядки", "GrechkaQuests_Pack_d55f155cff06" },
            { "Соберите сто единиц травяного лекарства. Это отдельная сельскохозяйственная веха.", "GrechkaQuests_Pack_bf974a4b7dfd" },
            { "На крайний случай", "GrechkaQuests_Pack_fa18460629b1" },
            { "Двадцать лекарств блестящих миров — серьёзная страховка. Покупки и трофеи подходят.", "GrechkaQuests_Pack_9368c9be95bc" },
            { "Камень, который слышит", "GrechkaQuests_Pack_390b66edb6f6" },
            { "Vanilla Psycasts Expanded: добудьте или купите 25 элтекса. Способы получения зависят от событий и доступной торговли.", "GrechkaQuests_Pack_33d2c8df674e" },
            { "Лицо псионика", "GrechkaQuests_Pack_237728d4806c" },
            { "Подготовьте элтексовую маску. Владение предметом не начисляет псиспособности и не требует немедленно его надеть.", "GrechkaQuests_Pack_e0409dc26f4b" },
            { "Медитация солнечной батареи", "GrechkaQuests_Pack_e83bebfc5dca" },
            { "Панель Eltex — мост между псионической и энергетической ветками Grechka.", "GrechkaQuests_Pack_412a3f62e5b5" },
            { "Литейная бронекостюмов", "GrechkaQuests_Pack_5ad42b017b99" },
            { "Литейная собирает тяжёлые бронекостюмы вокруг выбранной пешки. Подготовьте требуемые материалы и учитывайте последствия этой операции для колониста. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_3bcfeddbad60" },
            { "Оружие на вырост", "GrechkaQuests_Pack_2ae278cf22ca" },
            { "Получите варкаскетный миниган Pirates: найдите, купите или изготовьте его. Тяжёлому бойцу понадобится тяжёлое оружие.", "GrechkaQuests_Pack_7f3cc8582b3f" },
            { "Деталь из другой эпохи", "GrechkaQuests_Pack_c1cb9b40815a" },
            { "The Generator: соберите 10 компонентов ARC. Сюжетные события и условия их получения определяет исходный мод.", "GrechkaQuests_Pack_2b063a27afcb" },
            { "Базовый ARC", "GrechkaQuests_Pack_040c4d1c4c04" },
            { "Вариант генератора ARC. Сравните его штатные условия работы и затраты с уже найденным ARC; это альтернативная конфигурация источника энергии, а не обязательная ступень после всех остальных. В Grechka World минимально нужен корпус T2. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_c619ddcd7725" },
            { "Холодная находка", "GrechkaQuests_Pack_270ee9fa2212" },
            { "Cryptoforge: получите криптотопор. Найденное, купленное и изготовленное оружие подходит одинаково.", "GrechkaQuests_Pack_ee61038fe395" },
            { "Холоднее гречневой каши", "GrechkaQuests_Pack_66e46c2f77a4" },
            { "Добавьте криптоболтер к арсеналу. Книга не запускает и не завершает события Cryptoforge вместо рассказчика.", "GrechkaQuests_Pack_aa536e44ae43" },
            { "Письменный стол", "GrechkaQuests_Pack_a8fc301208d1" },
            { "Письменный стол позволяет создавать книги. Выберите тему, назначьте автора и создайте первую полезную книгу для библиотеки колонии. В Grechka World минимально нужен корпус T1. Это необязательная ветка: для перехода к следующему тиру не нужно строить все варианты.", "GrechkaQuests_Pack_4465d179cb08" },
            { "Инструкция к колонии", "GrechkaQuests_Pack_71c43fa5dc90" },
            { "Получите книгу ремесла. Задача проверяет предмет; чтение и обучение работают по правилам Books Expanded.", "GrechkaQuests_Pack_3360230bbc5e" },
            { "Полка полезных знаний", "GrechkaQuests_Pack_386a6a492a45" },
            { "Пополните библиотеку книгами медицины, строительства и готовки. Каждая книга отмечается отдельно; потом её можно отдать читателю или продать.", "GrechkaQuests_Pack_2fdda7f44abc" },
            { "Книга строительства", "GrechkaQuests_Pack_dc75d993dcbb" },
            { "Книга готовки", "GrechkaQuests_Pack_879e434bd94d" },
            { "Стрелять до прихода рейдеров", "GrechkaQuests_Pack_330d87645b69" },
            { "Misc. Training: поставьте стрелковую мишень. Сам навык этим квестом не повышается.", "GrechkaQuests_Pack_abc1285614c0" },
            { "Дипломатия кулака", "GrechkaQuests_Pack_5f80b525f87a" },
